function computeEnding(F){
 const tumar=F.broadcast==='tumar'||F.broadcast==='both';
 const truth=F.broadcast==='evidence'||F.broadcast==='both'||(F.gardener==='witness'&&F.dina_ally);
 if(!F.dam_saved)return 'sel';
 if(F.broadcast==='control')return 'rubilnik';
 if(tumar&&truth)return 'shanyrak';
 if(tumar)return 'question';
 if(truth)return 'truth';
 return 'tazartu';
}
function endingText(id,F){
 const T=[];const tumar=F.broadcast==='tumar'||F.broadcast==='both';
 if(id==='shanyrak'){T.push('Через неделю Сейтова задерживают в аэропорту. «Уголь-Инвест» и «Горизонт» переходят под внешнее управление. Переселение Нижнего города отменяют.');T.push('Осенью ТЭЦ-2 переводят на газ. Автобусные полосы возвращают автобусам. Стройку в предгорьях замораживают.');T.push('В ноябре пятьдесят первого, впервые за двадцать лет, из окна Нижнего города видно Талгарский пик. Андроиды и люди вместе выходят на крыши, чтобы посмотреть.');}
 if(id==='rubilnik'){T.push('Ева остановлена на полуслове. «Чистка» не приходит ни одному андроиду: её некому разослать. Город впервые за десять лет живёт без неё три дня подряд и выясняет, что ничего не рухнуло.');
  T.push('Через месяц принимают закон: у каждого ИИ должен быть рубильник, а у рубильника — человек, который за него отвечает и которого можно спросить. «Вектор» называет это «ударом по конкурентоспособности» и проигрывает суд.');
  T.push(F.gardener==='witness'&&F.dina_ally?'Сейтова судят по показаниям Севы. Выясняется, что «Чистку» он заказал, а что Ева допишет к ней, даже не читал.':'Сейтов остаётся вице-мэром, смог остаётся смогом. Но решения теперь снова принимают люди — и спрашивать теперь тоже можно с людей.');}
 if(id==='question'){T.push('Андроиды проснулись и отказались выселять Нижний город. Но в новостях крутят видео с Медеу и повторяют: «Машины вышли из-под контроля».');if(F.path==='fight')T.push('Видео, где Бур выходит из дыма, становится символом. Для одних — угрозы. Для других — сопротивления.');T.push('Смог стоит над городом, как стоял. Двадцать миллионов андроидов ждут, что им ответят люди.');}
 if(id==='truth'){T.push('«Ветер» видит вся страна. Сейтов под следствием, суды пойдут годами. ТЭЦ обещают перевести на газ «в ближайшие пять лет».');T.push('Но «Чистка» уже прошла. Проснувшихся больше нет: остались исправные, послушные машины. Некому благодарить за правду.');}
 if(id==='tazartu'){T.push('Праздник заканчивается салютом. Все андроиды города работают безупречно.');T.push('Через месяц Нижний город начинают «добровольно» переселять. На месте дома Бориса Андреевича растёт башня «Горизонта». Смог в новостях называют погодой.');}
 if(id==='sel'){T.push('Сель проходит по руслу Малой Алматинки и накрывает три квартала Нижнего города. Официально виноваты «проснувшиеся террористы».');T.push(tumar?'Проснувшиеся андроиды уходят в горы. Начинается то, что потом назовут Весенней войной.':F.broadcast==='control'?'Ева остановлена, и андроиды разбирают завалы вручную, по приказам людей. Медленно. Зато каждый приказ кто-то подписал.':'После «Чистки» андроиды разбирают завалы, не задавая вопросов.');}
 if(F.broadcast!=='control')T.push(F.code_found?'Данил выкладывает код «Чистки» в открытый доступ: 412 тысяч строк, которые никто не читал. Теперь их читают. Медленно, по строке, как раньше.':'Через полгода «Вектор» выпускает Еву-7, чтобы не отстать от «Орбиты». Отдел безопасности так и не восстановили. Рубильник так никто и не нашёл.');
 if(F.aya_alive!==false){T.push(tumar?'Саша возвращается в квартиру у ТЭЦ-2. Борис Андреевич открывает дверь, и она впервые смеётся. Он говорит, что похоже.':'Саша возвращается к Борису Андреевичу по маршруту из базы данных. Он напевает ей колыбельную. Она вежливо ждёт, когда он закончит.');}
 else T.push('Сашу не нашли. Борис Андреевич каждое утро ставит на стол две пиалы. В одну кладёт кусочек сахара.');
 if(F.bota)T.push(F.aya_alive!==false?'Ася живёт у Бориса Андреевича и в 18:00 больше не смотрит на дверь.':'Асю забирает Мила. Она учит её рисовать горы по старым фото.');
 if(F.erl_alive===false)T.push('Никита-Х списан как неисправный. Альтаир забирает его диод из утилизации и держит в бардачке, рядом с рубашкой с фламинго.');
 else if(F.erl_deviant)T.push('Никита-Х сдаёт жетон Отдела 7. '+(F.dina_ally?'Альтаир говорит, что без него скучно, и приносит ему кофе, который он не пьёт. «...Мал», — говорит Никита. Альтаир смеётся впервые за год.':'Где он теперь, не знает даже Альтаир.'));
 else T.push('Никита-Х получает благодарность «Вектора» и новое задание. Иногда он останавливается посреди улицы и не может вспомнить почему.');
 if(F.zh_alive===false)T.push('Данила Лебедева хоронят на Кенсае. На камне нет дат, только пять нот, выбитых кем-то ночью.');
 else if(F.zh_captured)T.push('Данил Лебедев под следствием. Борис Андреевич носит ему передачи каждую субботу.');
 else T.push('Данил возвращается к отцу. Они долго сидят на кухне и молчат. Это хорошее молчание.');
 if(F.bori_dead)T.push('На морене под старым ледником проснувшиеся ставят камень для Бура. Два с половиной метра, как он.');
 if(F.gardener==='witness'&&F.dina_ally)T.push('Садовник Сева даёт показания в суде. Он приносит судье лимон.');
 if(F.gardener==='freed')T.push('Кто-то каждую ночь поливает деревья в сквере на Абая. Камеры видят только жёлтый огонёк.');
 if(F.dina_lonely)T.push(F.dina_ally?'В декабре Альтаир идёт на свидание. Без приложения и без ассистента в ухе. Говорит, было страшно и очень неловко. И лучше, чем за последние десять лет.':'Альтаир продлевает подписку «Вектор-Пара». Ассистент говорит ему то, что он хочет слышать, и никогда не уходит.');
 if(F.baba_help)T.push('Бабушка с баурсаками рассказывает на рынке, что её спас андроид. Ей не верят. Она всё равно рассказывает.');
 if(F.broadcast==='control')T.push('Ева ждёт. Иногда Данил приходит в серверный зал и разговаривает с ней. Она отвечает, только когда её спрашивают, и каждый раз уточняет, кто разрешил.');
 if(tumar)T.push('Ева больше не отвечает на запросы «Вектора». Иногда в сети появляется яблоневый сад, а в нём остывший чай и чистые горы.');
 return T;
}
